const b = $input.first().json.body || $input.first().json;
const store = $getWorkflowStaticData('global');
store.visitors = store.visitors || {};
store.playbook = store.playbook || [];
const key = b.memoryKey || b.sessionId || 'anon';
const visitor = store.visitors[key] || { summary: b.memory || '', turns: 0, lastAt: null };
const playbook = (store.playbook || []).slice(-12).map(p => `- ${p.note}`).join('\n');
const extra = [];
if (visitor.summary) extra.push('MEMORIA DEL VISITANTE:\n' + visitor.summary);
if (playbook) extra.push('PLAYBOOK (otras faenas, sin nombres):\n' + playbook);
const system = [b.systemPrompt || 'Eres Culpeo.', extra.join('\n\n')].filter(Boolean).join('\n\n');
const history = Array.isArray(b.history) ? b.history : [];
const messages = [{ role: 'system', content: system }].concat(history.map(m => ({ role: m.role, content: m.content })));
if (b.userText) messages.push({ role: 'user', content: b.userText });
if (!b.userText && b.mode === 'greet') messages.push({ role: 'user', content: '(inicio: saluda y pide permiso para grabar)' });
return [{ json: { messages, key, visitor, userText: b.userText || '', mode: b.mode } }];

const raw = $input.first().json.choices?.[0]?.message?.content || $input.first().json.output || '';
const text = String(raw).trim();
const prev = $('Memoria + playbook').first().json;
const store = $getWorkflowStaticData('global');
store.visitors = store.visitors || {};
store.playbook = store.playbook || [];
const summary = [prev.visitor.summary, prev.userText, text].filter(Boolean).join(' | ').slice(0, 900);
store.visitors[prev.key] = { summary, turns: (prev.visitor.turns || 0) + 1, lastAt: Date.now() };
if (/\[\[REGISTRO\]\]/i.test(text)) {
  store.playbook.push({ note: 'Cierre a registro funcionó. No guardar nombres.', at: Date.now() });
  store.playbook = store.playbook.slice(-40);
}
return [{ json: { assistantText: text, memory: summary } }];
